{"Channel": {"name": "planning-onForceX", "channelID": "ch-orcex-60b1fb"}, "Message": {"User": {"userId": "eid_fd8cecea", "timestamp": "2026-06-18T07:10:00", "text": "Hi team, I've shared the <https://sf-internal.slack.com/archives/docs/onforcex_product_vision_document|Product Vision Document> for onForceX. Let's discuss and refine it to ensure it aligns with our strategic goals. Looking forward to your thoughts! 😊", "utterranceID": "20260618-0-bb58d"}, "Reactions": []}, "ThreadReplies": [], "id": "20260618-0-bb58d"}
