{"Channel": {"name": "planning-CollaborateForce", "channelID": "ch-abaix-c92927"}, "Message": {"User": {"userId": "eid_1e7c8290", "timestamp": "2026-06-13T20:29:00", "text": "Hi team, I've shared the <https://sf-internal.slack.com/archives/docs/abaix_technical_specifications_document|Technical Specifications Document> for abAIX. Let's discuss any feedback or suggestions you might have. 😊", "utterranceID": "20260613-0-80fc2"}, "Reactions": []}, "ThreadReplies": [], "id": "20260613-0-80fc2"}
