{"Channel": {"name": "planning-PersonalizeForce", "channelID": "ch-zeaix-feedce"}, "Message": {"User": {"userId": "eid_caa2e58d", "timestamp": "2026-06-05T07:32:00", "text": "@Charlie Brown, that sounds like a significant hurdle. How does this affect smaller businesses or niche industries?", "utterranceID": "20260902-1-5bdb2"}, "Reactions": []}, "ThreadReplies": [], "id": "20260902-1-5bdb2"}
