{"Channel": {"name": "planning-shAIX", "channelID": "ch-shaix-1539d5"}, "Message": {"User": {"userId": "eid_5b61c55e", "timestamp": "2026-09-14T17:29:00", "text": "Hi team, QA team found some issues in the last release of shAIX. The report came from QA Specialist eid_c7622c8e. Let's discuss.", "utterranceID": "20260906-0-f4f60"}, "Reactions": []}, "ThreadReplies": [], "id": "20260906-0-f4f60"}
{"Channel": {"name": "planning-shAIX", "channelID": "ch-shaix-1539d5"}, "Message": {"User": {"userId": "eid_5a940dab", "timestamp": "2026-09-14T17:31:00", "text": "Thanks for the update, Charlie. What exactly did they find?", "utterranceID": "20260906-1-0a52b"}, "Reactions": []}, "ThreadReplies": [], "id": "20260906-1-0a52b"}
